from dataclasses import dataclass

@dataclass(order=True)
class V:
    major: int
    minor: int = 0

print(V(1, 2) < V(1, 3), V(1) == V(1, 0), V(2, 0))

class A:
    def hi(self):
        return "A"

class B(A):
    def hi(self):
        return "B" + super().hi()

class C(A):
    def hi(self):
        return "C" + super().hi()

class D(B, C):
    def hi(self):
        return "D" + super().hi()

print(D().hi(), [k.__name__ for k in D.__mro__])

class Point:
    def __init__(self, x, y):
        self.x, self.y = x, y

    def __eq__(self, other):
        return (self.x, self.y) == (other.x, other.y)

    def __hash__(self):
        return id(self)

import heapq

class Task:
    def __init__(self, priority):
        self.priority = priority

    def __lt__(self, other):
        return self.priority < other.priority

def build(priorities):
    heap = []
    for p in priorities:
        heapq.heappush(heap, Task(p))
    return heap
